import { useLocation, useNavigate } from "react-router-dom";
import { useState } from "react";
import Swal from "sweetalert2";

// Datos simulados mientras se entrena el modelo
const MOCK_RESULT = {
  enfermedad: "Sigatoka Negra",
  confianza: 94.5,
  nivel_riesgo: "Alto",
  descripcion:
    "La Sigatoka negra es una enfermedad fúngica causada por Mycosphaerella fijiensis. Es considerada la enfermedad foliar más destructiva del banano y plátano a nivel mundial. Afecta directamente las hojas, reduciendo la capacidad fotosintética de la planta.",
  sintomas: [
    "Manchas pequeñas de color pardo amarillento en el haz de la hoja",
    "Las manchas evolucionan a rayas de color marrón oscuro",
    "Centro de las lesiones de color gris con bordes amarillos",
    "Necrosis foliar severa en etapas avanzadas",
    "Maduración prematura del fruto",
  ],
  tratamientos: [
    "Aplicar fungicidas sistémicos (triazoles o estrobilurinas) de forma preventiva",
    "Eliminar y destruir hojas infectadas para reducir el inóculo",
    "Mantener buena ventilación en la plantación espaciando plantas",
    "Uso de variedades resistentes como FHIA-01 o FHIA-21",
    "Monitoreo constante cada 7-14 días durante la época lluviosa",
  ],
};

export default function Result() {
  const navigate = useNavigate();
  const location = useLocation();
  const [activeTab, setActiveTab] = useState("info");

  // Usa datos reales si vienen del backend, si no usa los simulados
  const result = location.state?.result || MOCK_RESULT;
  const imageUrl = location.state?.imageUrl || null;

  const riskConfig = {
    Alto: {
      badge: "bg-red-100 text-red-700 border border-red-200",
      bar: "bg-red-500",
      icon: "🔴",
    },
    Medio: {
      badge: "bg-amber-100 text-amber-700 border border-amber-200",
      bar: "bg-amber-500",
      icon: "🟡",
    },
    Bajo: {
      badge: "bg-green-100 text-green-700 border border-green-200",
      bar: "bg-green-500",
      icon: "🟢",
    },
    Ninguno: {
      badge: "bg-green-100 text-green-700 border border-green-200",
      bar: "bg-green-500",
      icon: "🟢",
    },
  };

  const risk = riskConfig[result.nivel_riesgo] || riskConfig["Medio"];

  const handleShare = () => {
    Swal.fire({
      title: "Compartir resultado",
      text: "¿Cómo quieres compartir este resultado?",
      icon: "question",
      showCancelButton: true,
      confirmButtonColor: "#3d5e35",
      cancelButtonColor: "#9ca3af",
      confirmButtonText: "📋 Copiar al portapapeles",
      cancelButtonText: "Cancelar",
      background: "#f5f2ec",
      customClass: { popup: "rounded-3xl" },
    }).then((result) => {
      if (result.isConfirmed) {
        const text = `Resultado: ${MOCK_RESULT.enfermedad}\nConfianza: ${MOCK_RESULT.confianza}%\nRiesgo: ${MOCK_RESULT.nivel_riesgo}`;
        navigator.clipboard.writeText(text);
        Swal.fire({
          title: "¡Copiado!",
          text: "El resultado fue copiado al portapapeles.",
          icon: "success",
          timer: 1500,
          showConfirmButton: false,
          background: "#f5f2ec",
          customClass: { popup: "rounded-3xl" },
        });
      }
    });
  };

  return (
    <div className="min-h-screen bg-[#f4f7f1] flex flex-col">

      {/* NAVBAR */}
      <header className="bg-white border-b border-gray-100 px-4 sm:px-6 py-3 flex items-center gap-3 sticky top-0 z-20 shadow-sm">
        <button
          onClick={() => navigate("/scan")}
          className="w-9 h-9 rounded-full bg-gray-100 flex items-center justify-center hover:bg-gray-200 transition shrink-0"
        >
          ←
        </button>
        <div className="flex items-center gap-2 flex-1 min-w-0">
          <div className="w-8 h-8 rounded-lg bg-green-700 flex items-center justify-center text-white text-sm shrink-0">
            🌿
          </div>
          <div className="min-w-0">
            <h1 className="font-bold text-sm leading-tight truncate">Resultado del análisis</h1>
            <p className="text-xs text-gray-500 hidden sm:block">Detección de Sigatoka negra</p>
          </div>
        </div>
        <button
          onClick={handleShare}
          className="flex items-center gap-1.5 bg-green-50 text-green-700 px-3 py-1.5 rounded-xl text-xs font-semibold hover:bg-green-100 transition shrink-0"
        >
          📤 Compartir
        </button>
      </header>

      <main className="flex-1 max-w-6xl mx-auto w-full px-4 sm:px-6 py-6">
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">

          {/* COLUMNA IZQUIERDA — imagen + resultado principal */}
          <div className="flex flex-col gap-4">

            {/* IMAGEN ANALIZADA */}
            <div className="bg-white rounded-3xl overflow-hidden">
              {imageUrl ? (
                <img
                  src={imageUrl}
                  alt="Hoja analizada"
                  className="w-full h-56 sm:h-64 object-cover"
                />
              ) : (
                <div className="w-full h-56 sm:h-64 bg-green-50 flex items-center justify-center">
                  <span className="text-5xl">🍃</span>
                </div>
              )}
              <div className="p-4">
                <div className="flex items-center justify-between mb-2">
                  <h2 className="font-bold text-base text-gray-800">{result.enfermedad}</h2>
                  <span className={`text-xs font-semibold px-2.5 py-1 rounded-full ${risk.badge}`}>
                    {risk.icon} {result.nivel_riesgo}
                  </span>
                </div>
                <p className="text-xs text-gray-500 mb-3">Banano · Detectado ahora</p>

                {/* BARRA DE CONFIANZA */}
                <div>
                  <div className="flex items-center justify-between mb-1">
                    <span className="text-xs text-gray-500">Precisión del modelo</span>
                    <span className="text-xs font-bold text-gray-800">{result.confianza}%</span>
                  </div>
                  <div className="w-full h-2 bg-gray-100 rounded-full overflow-hidden">
                    <div
                      className={`h-full rounded-full transition-all duration-700 ${risk.bar}`}
                      style={{ width: `${result.confianza}%` }}
                    />
                  </div>
                </div>
              </div>
            </div>

            {/* NIVEL DE RIESGO */}
            <div className="bg-white rounded-3xl p-4">
              <h3 className="font-semibold text-sm text-gray-800 mb-3">Nivel de riesgo</h3>
              <div className="flex items-center gap-3">
                <div className="flex-1 h-3 bg-gray-100 rounded-full overflow-hidden">
                  <div
                    className={`h-full rounded-full ${risk.bar}`}
                    style={{
                      width:
                        result.nivel_riesgo === "Alto"
                          ? "90%"
                          : result.nivel_riesgo === "Medio"
                          ? "55%"
                          : "20%",
                    }}
                  />
                </div>
                <span className={`text-xs font-bold px-2.5 py-1 rounded-full ${risk.badge}`}>
                  {result.nivel_riesgo}
                </span>
              </div>
              <div className="flex justify-between mt-1">
                <span className="text-[10px] text-gray-400">Bajo</span>
                <span className="text-[10px] text-gray-400">Alto</span>
              </div>
            </div>

            {/* BOTONES DE ACCIÓN */}
            <div className="flex gap-3">
              <button
                onClick={() => navigate("/scan")}
                className="flex-1 bg-white border-2 border-green-200 hover:bg-green-50 
                           transition text-green-700 py-3 rounded-2xl text-sm font-semibold
                           flex items-center justify-center gap-2"
              >
                🔄 Nuevo escaneo
              </button>
              <button
                onClick={() => navigate("/map")}
                className="flex-1 bg-green-700 hover:bg-green-800 transition text-white 
                           py-3 rounded-2xl text-sm font-semibold
                           flex items-center justify-center gap-2"
              >
                🗺️ Ver en mapa
              </button>
            </div>
          </div>

          {/* COLUMNA DERECHA — tabs con info detallada */}
          <div className="lg:col-span-2 flex flex-col gap-4">

            {/* TABS */}
            <div className="bg-white rounded-3xl p-1.5 flex gap-1">
              {[
                { key: "info", label: "📋 Información" },
                { key: "sintomas", label: "🔍 Síntomas" },
                { key: "tratamiento", label: "💊 Tratamiento" },
              ].map((tab) => (
                <button
                  key={tab.key}
                  onClick={() => setActiveTab(tab.key)}
                  className={`flex-1 py-2.5 rounded-2xl text-xs sm:text-sm font-semibold transition ${
                    activeTab === tab.key
                      ? "bg-green-700 text-white"
                      : "text-gray-500 hover:bg-gray-50"
                  }`}
                >
                  {tab.label}
                </button>
              ))}
            </div>

            {/* CONTENIDO TABS */}
            <div className="bg-white rounded-3xl p-5 sm:p-6 flex-1">

              {/* TAB: INFORMACIÓN */}
              {activeTab === "info" && (
                <div className="space-y-4">
                  <div>
                    <h3 className="font-bold text-base text-gray-800 mb-2 flex items-center gap-2">
                      🦠 Sobre esta enfermedad
                    </h3>
                    <p className="text-sm text-gray-600 leading-relaxed">
                      {result.descripcion}
                    </p>
                  </div>

                  <div className="grid grid-cols-2 sm:grid-cols-3 gap-3 mt-4">
                    <div className="bg-red-50 rounded-2xl p-3 text-center">
                      <p className="text-xl font-bold text-red-600">{result.confianza}%</p>
                      <p className="text-xs text-gray-500 mt-0.5">Precisión</p>
                    </div>
                    <div className={`rounded-2xl p-3 text-center ${risk.badge}`}>
                      <p className="text-xl font-bold">{result.nivel_riesgo}</p>
                      <p className="text-xs mt-0.5 opacity-70">Nivel riesgo</p>
                    </div>
                    <div className="bg-green-50 rounded-2xl p-3 text-center col-span-2 sm:col-span-1">
                      <p className="text-xl font-bold text-green-700">IA</p>
                      <p className="text-xs text-gray-500 mt-0.5">Detección</p>
                    </div>
                  </div>

                  <div className="bg-amber-50 border border-amber-100 rounded-2xl p-4 flex items-start gap-3 mt-2">
                    <span className="text-lg shrink-0">⚠️</span>
                    <p className="text-xs text-amber-800">
                      Este resultado es orientativo. Para decisiones de manejo crítico, consulta con un agrónomo especialista en cultivos de banano.
                    </p>
                  </div>
                </div>
              )}

              {/* TAB: SÍNTOMAS */}
              {activeTab === "sintomas" && (
                <div>
                  <h3 className="font-bold text-base text-gray-800 mb-4 flex items-center gap-2">
                    🔍 Síntomas identificados
                  </h3>
                  <div className="space-y-3">
                    {result.sintomas.map((sintoma, i) => (
                      <div
                        key={i}
                        className="flex items-start gap-3 p-3 bg-red-50/50 rounded-2xl border border-red-100"
                      >
                        <div className="w-6 h-6 rounded-full bg-red-100 text-red-600 flex items-center justify-center text-xs font-bold shrink-0 mt-0.5">
                          {i + 1}
                        </div>
                        <p className="text-sm text-gray-700">{sintoma}</p>
                      </div>
                    ))}
                  </div>
                </div>
              )}

              {/* TAB: TRATAMIENTO */}
              {activeTab === "tratamiento" && (
                <div>
                  <h3 className="font-bold text-base text-gray-800 mb-4 flex items-center gap-2">
                    💊 Recomendaciones de tratamiento
                  </h3>
                  <div className="space-y-3">
                    {result.tratamientos.map((tratamiento, i) => (
                      <div
                        key={i}
                        className="flex items-start gap-3 p-3 bg-green-50/50 rounded-2xl border border-green-100"
                      >
                        <div className="w-6 h-6 rounded-full bg-green-100 text-green-700 flex items-center justify-center text-xs font-bold shrink-0 mt-0.5">
                          {i + 1}
                        </div>
                        <p className="text-sm text-gray-700">{tratamiento}</p>
                      </div>
                    ))}
                  </div>

                  <div className="bg-green-50 border border-green-100 rounded-2xl p-4 mt-4 flex items-start gap-3">
                    <span className="text-lg shrink-0">💡</span>
                    <p className="text-xs text-green-800">
                      La detección temprana y el tratamiento oportuno pueden salvar hasta el 80% de tu cultivo. Actúa de inmediato.
                    </p>
                  </div>
                </div>
              )}
            </div>

            {/* NOTA SIMULACIÓN */}
            <div className="bg-blue-50 border border-blue-100 rounded-2xl p-3 flex items-start gap-2">
              <span className="text-base shrink-0">🤖</span>
              <p className="text-xs text-blue-700">
                <strong>Datos de demostración:</strong> Este resultado es simulado. Una vez entrenado el modelo YOLOv8, aquí aparecerán los resultados reales del análisis de la imagen.
              </p>
            </div>

          </div>
        </div>
      </main>
    </div>
  );
}
